class Solution {
public:
    vector<int> findSubtreeSizes(vector<int>& parent, string s) {
       int n = s.length();
       vector<vector<int>> v(n,vector<int>);
       for(int i=0;i<n;i++)
       {
           int x = parent[i];
           vector<int> temp;

           while(x!=-1)
           {
               temp.push_back(x);
           }
           v[i].push_back(temp);
       }
       for(int i=0;i<n;i++)
       {
           int ns = v[i].size();
           for(int j=0;j<ns;j++)
           {
               if(s[i]==s[v[i][j])
               {
                   parent[i]=v[i][j];
                   break;
               }
           }
       }

    }
};
